mapper.select:
SELECT id, conversation_id, role, content, model, token_usage, segment_id, created_at
FROM ai_message
WHERE conversation_id = #{conversationId}
ORDER BY id ASC
LIMIT #{limit}

SELECT id, conversation_id, role, content, model, token_usage, segment_id, created_at
FROM (
    SELECT * FROM ai_message
    WHERE conversation_id = #{conversationId}
    ORDER BY id DESC
    LIMIT #{limit}
) recent
ORDER BY id ASC

SELECT id, conversation_id, role, content, model, token_usage, segment_id, created_at
FROM (
    SELECT * FROM ai_message
    WHERE conversation_id = #{conversationId} AND segment_id = #{segmentId}
    ORDER BY id DESC
    LIMIT #{limit}
) recent
ORDER BY id ASC

SELECT id, conversation_id, role, content, model, token_usage, segment_id, created_at
FROM ai_message
WHERE conversation_id = #{conversationId}
  AND segment_id = #{segmentId}

  AND id > #{coveredId}

ORDER BY id ASC
LIMIT #{limit}

SELECT COUNT(*)
FROM ai_message
WHERE conversation_id = #{conversationId}
  AND segment_id = #{segmentId}

  AND id > #{coveredId}

mapper.update:
UPDATE ai_message
SET segment_id = #{segmentId}
WHERE id = #{id}
